// Cognitive catalogue scopes reuse admitted evidence; placebo mechanisms retain assay identity.
const sources = [], entities = [], claims = [], relations = [], studies = [], comparisons = [], readiness = [];
const sourceIndex = new Map(), studyIndex = new Map(), findingIndex = new Map();
const extent = "main-results-methods-and-figure-legends-supplement-unread";
const commonLimit = "Source reconstruction is not raw-data replay, laboratory reproduction or independent scientific review. No universal cognitive construction rule, smallest circuit, causal weight or ontological stage is established.";
function publication(id, title, authors, year, doi, url, journal, volume, issue, pages, locators, limit, readExtent = extent) {
  const source = { id, kind: "research-publication", title, authors, year, doi, url, path: null, sha256: null,
    review: { extent: readExtent, locators, limit } };
  sources.push(source); sourceIndex.set(id, { source, journal, volume, issue, pages });
}
function citation(sourceId, locator, role = "supports") {
  return { sourceId, locator, role, note: "Only the declared passage and preparation support this statement; observations, proposed mechanisms and catalogue interpretation remain distinct." };
}
function node(id, name, kind, description, claimIds, sourceCoordinates, openObligations = [], status = "evidence-scoped") {
  const nodeId = `cog:${id}`;
  entities.push({ id: nodeId, name, kind, description, claimIds, status, sourceCoordinates,
    openObligations: [...openObligations, commonLimit], level: 6 });
  readiness.push({ nodeId, role: kind === "context" ? "experimental-context" : kind === "definition" ? "definition" : kind === "hypothesis" ? "hypothesis" : "scoped-phenomenon",
    denotes: description, instanceAdmission: "none", claimIds });
  return nodeId;
}
function study(id, sourceId, system, preparation, observable, finding, limitations, indexes) {
  const meta = sourceIndex.get(sourceId), locators = indexes.map(i => meta.source.review.locators[i]);
  const methodId = `M-cog-${id}`, limits = [meta.source.review.limit, ...limitations, commonLimit];
  claims.push({ id: methodId, kind: "method", statement: preparation, scope: system, status: "method-contract",
    citations: locators.map(locator => citation(sourceId, locator, "method")), checkIds: [], limitations: limits, contextIds: [id] });
  node(`${id}-context`, `${id}: acquisition context`, "context", preparation, [methodId], locators.map(locator => ({ sourceId, locator })), limits, "definition");
  const record = { id, sourceId, studyType: "primary-experiment", doi: meta.source.doi,
    journal: meta.journal, volume: meta.volume, issue: meta.issue, pages: meta.pages, system,
    preparation, observable, finding, limitations: limits, readExtent: meta.source.review.extent, reviewedLocators: locators,
    metadataCheckedAt: "2026-10-24", metadataUrl: `https://doi.org/${meta.source.doi}`,
    correctionCheck: "The displayed PMC primary record, bibliographic identifiers and DOI-specific correction/erratum searches were inspected. No explicit notice resolving these scientific boundaries was identified. This bounded check is not exhaustive correction surveillance; separate supplements and original data were not replayed." };
  studies.push(record); studyIndex.set(id, { record, methodId, locators, limits });
}
function observation(id, name, studyId, statement, limitations = [], status = "publication-supported") {
  const context = studyIndex.get(studyId), claimId = `C-cog-${id}`;
  claims.push({ id: claimId, kind: "review-finding", statement, scope: context.record.system, status,
    citations: context.locators.map(locator => citation(context.record.sourceId, locator)), checkIds: [],
    limitations: [...context.limits, ...limitations], contextIds: [studyId] });
  node(id, name, "scoped-process", statement, [claimId, context.methodId], context.locators.map(locator => ({ sourceId: context.record.sourceId, locator })), limitations);
  relations.push({ id: `neural-systems:${studyId}-measures-${id}`, source: `cog:${studyId}-context`, target: `cog:${id}`,
    kind: "descriptive", role: "measurement-context", assertion: "This acquisition context fixes the participants, manipulation, timing and endpoint of the reported observation.",
    claimIds: [context.methodId, claimId], contextIds: [studyId] });
  findingIndex.set(id, { claimId, studyId }); return claimId;
}
function operating(source, target, studyId, assertion, bearer, input, observable, limit) {
  const context = studyIndex.get(studyId), a = findingIndex.get(source), b = findingIndex.get(target);
  if (a.studyId !== studyId || b.studyId !== studyId) throw new Error("Cognitive functional endpoints must share the tested preparation");
  relations.push({ id: `neural-systems:${source}-supports-${target}`, source: `cog:${source}`, target: `cog:${target}`,
    kind: "functional-support", role: "scoped-operating-support", assertion,
    claimIds: [a.claimId, b.claimId, context.methodId], contextIds: [studyId],
    carrier: { contextIds: [studyId], citations: context.locators.map(locator => ({ sourceId: context.record.sourceId, locator })),
      interpretation: { bearer, input, observable, limit }, countingStatus: "unoperationalized", numericalAdmission: "none" } });
}

