export const CARD_SCOPES = [];
function card(index, originalName, slug, scope, evidence, topics, parents, unresolved) {
  const claimId = `D-cog-${slug}`, locator = `Card 6.${index} scope contract`;
  const bibliography = index === 19 ? [citation("fodor1975-language-thought",
    sourceIndex.get("fodor1975-language-thought").source.review.locators[0], "provenance")] : [];
  claims.push({ id: claimId, kind: "author-definition", statement: scope,
    scope: `Reviewed catalogue card 6.${index}; evidence reuse is representational and does not create a physical dependency.`,
    status: "definition", citations: [citation("legacy-6", `/${index}`, "provenance"), citation("neural-systems-review", locator), ...bibliography],
    checkIds: [], limitations: [...excludedDefaults, ...unresolved, commonLimit] });
  node(slug, `${originalName}: reviewed scope`, "definition", scope, [claimId], [{ sourceId: "legacy-6", locator: `/${index}` }, { sourceId: "neural-systems-review", locator }], [...excludedDefaults, ...unresolved], "definition");
  const pairs = evidence.map(entry => typeof entry === "string" ? [`cog:${entry}`, findingIndex.get(entry).claimId] : entry);
  for (const [nodeId, evidenceClaim] of pairs) relations.push({ id: `neural-systems:${nodeId.replace(":", "-")}-defines-${slug}`,
    source: nodeId, target: `cog:${slug}`, kind: "descriptive", role: "definition-dependency",
    assertion: "This existing source-bound observation or attributed construct qualifies the reviewed catalogue scope. The link is representational; it asserts no physical cause, neural necessity, construction order or transfer of experimental support to an unresolved mechanism.", claimIds: [claimId, evidenceClaim] });
  const qualify = ([topic, disposition, reason, selected = []]) => ({ topic, disposition, reason, claimIds: [claimId, ...selected] });
  const localStudyIds = [...new Set(evidence.filter(entry => typeof entry === "string").map(id => findingIndex.get(id).studyId))];
  CARD_SCOPES.push({ code: `6.${index}`, sourceIndex: index, originalName, scope,
    nodeIds: [`cog:${slug}`, ...pairs.map(([id]) => id), ...localStudyIds.map(id => `cog:${id}-context`)],
    claimIds: [...new Set([claimId, ...pairs.map(([, id]) => id), ...localStudyIds.map(id => studyIndex.get(id).methodId)])],
    assertions: topics.map(qualify), parentDispositions: parents.map(([parentCode, disposition, reason, selected]) => {
      const { topic, ...rest } = qualify([parentCode, disposition, reason, selected]); return { parentCode, ...rest };
    }), excludedDefaults: [...excludedDefaults], unresolved });
}

